static int rtl_disable_eee_bottom(struct r8152 *tp)
{
	int i, ret = -EINVAL;

	for (i = 0; i < 50; i++) {
		if (!(rtl8152_get_speed(tp) & LINK_STATUS)) {
			ret = ocp_word_clr_bits(tp, MCU_TYPE_PLA, PLA_EEE_CR,
						EEE_RX_EN);
			break;
		}
		msleep(20);
	}

	return (ret < 0) ? ret : 0;
}
